using Xunit;
using HakutaiKagami.Core.Contracts;
namespace HakutaiKagami.Tests;
public sealed class NewGameNpcRoutineTests
{
    static ContractWorld New(string? policy=NewGameNpcRoutine.Policy)=>NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,policy);
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    [Fact] public void LegacyPolicyIsNotSilentlyEnabled(){var w=New(null);Assert.Null(w.NpcWork);Assert.Null(w.NewGame!.NpcRoutinePolicy);var s=new WorldSession(w);At(s,20);Assert.Null(s.DiagnosticSnapshot().NpcWork);Assert.Empty(s.DiagnosticSnapshot().Requests);}
    [Fact] public void FirstSharedTickStartsFiveNpcOwnJobsWithoutPlayerOrders(){var s=new WorldSession(New());At(s,1);var w=s.DiagnosticSnapshot();Assert.Equal(5,w.Requests.Length);Assert.Equal(5,w.NpcWork!.Decisions.Length);Assert.All(w.Requests,r=>{Assert.NotEqual(w.PlayerControl,r.Intent.Actor);Assert.Equal(r.Intent.Actor,r.Intent.Executor);Assert.Equal(ActionKind.Inspect,r.Intent.Action);});Assert.Empty(s.GetActorView(s.PlayerControl).Messages);Assert.False(RegionalWork.Enabled(w));Assert.False(NpcWork.Enabled(w));}
    [Fact] public void NpcOwnReportPreventsUnnecessaryRepeatedJobs(){var s=new WorldSession(New());At(s,8);Assert.Equal(5,s.DiagnosticSnapshot().Requests.Length);Assert.All(s.DiagnosticSnapshot().Tasks,t=>Assert.Equal(ExecutionPhase.Completed,t.Execution));At(s,3600);Assert.Equal(5,s.DiagnosticSnapshot().Requests.Length);At(s,3601);Assert.Equal(5,s.DiagnosticSnapshot().Requests.Length);Assert.All(s.DiagnosticSnapshot().Requests.GroupBy(r=>r.Intent.Actor),g=>Assert.Single(g));}
    [Fact] public void OtherHiddenFactsCannotChangeOwnNpcInputs(){var a=New();var actor=new EntityId("person:shingen");var b=ContractJson.Copy(a);b.Characters=b.Characters.Select(c=>c.Id==a.PlayerControl?c with{WillObey=false}:c).ToArray();b.Locations=b.Locations.Select(l=>l.Actor==a.PlayerControl?l with{Site=new("site:shuri")}:l).ToArray();Assert.Equal(ContractJson.Write(NewGameNpcRoutine.Inputs(a,actor,0,0)),ContractJson.Write(NewGameNpcRoutine.Inputs(b,actor,0,0)));}
    [Fact] public void InsufficientEventBudgetCannotPartiallyRunNpcRound(){var s=new WorldSession(New());s.SetPaused(false);string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());var r=s.AdvanceTo(1,eventBudget:1);Assert.Equal("EventBudget",r.StopReason);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));At(s,1);Assert.Equal(5,s.DiagnosticSnapshot().Requests.Length);}
    [Fact] public void UnrecognizedPolicyAndForgedDecisionAreRejected(){Assert.Throws<InvalidDataException>(()=>New("unknown"));var s=new WorldSession(New());At(s,1);var w=s.DiagnosticSnapshot();var d=w.NpcWork!.Decisions[0];w.NpcWork.Decisions[0]=d with{Reason="forged"};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void ActorAndInputsCannotBeForged(){var s=new WorldSession(New());At(s,1);var w=s.DiagnosticSnapshot();var d=w.NpcWork!.Decisions[0];w.NpcWork.Decisions[0]=d with{Actor=w.PlayerControl};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();d=w.NpcWork!.Decisions[0];w.NpcWork.Decisions[0]=d with{Inputs=d.Inputs with{InspectionPermit=false}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(7)][InlineData(3600)][InlineData(3601)] public void ActiveNpcJobsAndSameFutureSurviveSave(int at){var initial=New();var s=new WorldSession(initial);At(s,at);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"npc-routine-"+Guid.NewGuid().ToString("N")),initial.Definitions);store.Save(s,"manual",initial.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));foreach(var x in new[]{s,host.Current})At(x,3608);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact] public void PriorProfilesKeepTheirOriginalInitialHashes(){foreach(var file in new[]{"pre-catalog-start-v1.json","pre-household-start-west-v2.json"}){var p=ContractJson.Read<NewCampaignProfile>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures",file)));Assert.Null(p.NpcRoutinePolicy);Assert.Equal(p.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(p)));}}
    [Fact] public void LongRouteTimeCannotCreatePeriodicUnneededHistory(){var s=new WorldSession(New());At(s,8);int decisions=s.DiagnosticSnapshot().NpcWork!.Decisions.Length;At(s,400000);Assert.Equal(5,s.DiagnosticSnapshot().Requests.Length);Assert.Equal(decisions,s.DiagnosticSnapshot().NpcWork!.Decisions.Length);Assert.True(decisions<=15);}
    [Fact] public void ActualPriorHouseholdProfileKeepsExactHashWithoutOptIn(){var p=ContractJson.Read<NewCampaignProfile>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","pre-routine-household-v3.json")));Assert.Null(p.NpcRoutinePolicy);Assert.Equal(6,p.Setup.People.Length);Assert.Equal("bc1ca5126363089b885fce3dbbb17f8620ad2b45032862d8a8f9f886eac95477",ContractJson.CanonicalHash(NewCampaignStore.Build(p)));}
    [Fact] public void NewProfilePinsPolicyAndCannotSilentlyRemoveIt(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"routine-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",20261022,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy);Assert.Equal(NewGameNpcRoutine.Policy,store.Read(p.Instance).NpcRoutinePolicy);Assert.Equal(p.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(p)));Assert.Throws<InvalidDataException>(()=>NewCampaignStore.Build(p with{NpcRoutinePolicy=null}));}
    [Fact] public void PolicyAndModulePresenceCannotBeMixed(){var on=New();on.NpcWork=null;Assert.Throws<InvalidDataException>(()=>new WorldSession(on));var off=New(null);off.NpcWork=new([]);Assert.Throws<InvalidDataException>(()=>new WorldSession(off));}
}
